export const dynamic = 'force-dynamic'

import { NextResponse } from 'next/server'
import { apiHandler } from '@/lib/apiHandler'
import { db } from '@/lib/db'
import { z } from 'zod'
import { declaredUtmReferenceSchema } from '@/lib/validation/declaredUtmReference'
import { validateCoordinateRange } from '@/lib/spatial/projectCrs'

// AUTO-GENERATED by api-row-sweep --apply — column types from migrations/*.sql + name heuristics.
// pg returns bigint/numeric as string, timestamptz as Date; nullable columns carry `| null`; REVIEW.
interface BoundaryMonumentRow {
  id: string
  monument_number: string
  monument_type: string
  boundary_name: string
  treaty_reference: string
  treaty_date: Date | null
  latitude: number | null
  longitude: number | null
  elevation: number | null
  easting: number | null
  northing: number | null
  utm_zone: number
  hemisphere: string
  datum: string
  epsg_code: string
  coordinate_epoch: number | null
  reference_frame: string | null
  observation_date: Date | null
  sigma_e: number | null
  sigma_n: number | null
  sigma_h: number | null
  sigma_en: number | null
  confidence_level: number | null
  physical_description: string | null
  material: string | null
  dimensions: string | null
  marker_text: string | null
  photo_url: string | null
  county: string | null
  sub_county: string | null
  locality: string | null
  sheet_number: string | null
  condition: string | null
  condition_notes: string | null
  last_inspected_date: Date | null
  last_inspected_by: string | null
  verification_status: string | null
  verified_by: string | null
  verified_date: Date | null
  verification_notes: string | null
  created_by: string | null
  created_at: Date
  updated_at: Date
  geom: string | null
  metadata: unknown | null
}

/**
 * GET /api/boundary-monuments
 *
 * Search boundary monuments by:
 *   - boundary_name (e.g., 'Kenya-Tanzania')
 *   - monument_number (e.g., 'KEN-TZ-042')
 *   - proximity (lat, lon, radiusKm)
 *   - verification_status
 *   - condition
 *
 * Returns: { data: BoundaryMonument[], count: number }
 */

const searchSchema = z.object({
  boundary_name: z.string().optional(),
  monument_number: z.string().optional(),
  lat: z.coerce.number().optional(),
  lon: z.coerce.number().optional(),
  radiusKm: z.coerce.number().optional(),
  verification_status: z.string().optional(),
  condition: z.string().optional(),
  limit: z.coerce.number().min(1).max(500).prefault(100),
})

export const GET = apiHandler(
  { auth: true, rateLimit: { max: 60, windowMs: 60000 } },
  async (req, _ctx) => {
    const { searchParams } = new URL(req.url)
    const params = searchSchema.parse(Object.fromEntries(searchParams))

    let sql = `SELECT * FROM boundary_monuments WHERE 1=1`
    const values: unknown[] = []
    let idx = 1

    if (params.boundary_name) {
      sql += ` AND boundary_name ILIKE $${idx++}`
      values.push(`%${params.boundary_name}%`)
    }
    if (params.monument_number) {
      sql += ` AND monument_number ILIKE $${idx++}`
      values.push(`%${params.monument_number}%`)
    }
    if (params.verification_status) {
      sql += ` AND verification_status = $${idx++}`
      values.push(params.verification_status)
    }
    if (params.condition) {
      sql += ` AND condition = $${idx++}`
      values.push(params.condition)
    }

    // Proximity search using ST_DWithin (geographic)
    if (params.lat !== undefined && params.lon !== undefined && params.radiusKm) {
      sql += ` AND geom IS NOT NULL AND ST_DWithin(geom, ST_SetSRID(ST_MakePoint($${idx}, $${idx + 1}), 4326)::geography, $${idx + 2})`
      values.push(params.lon, params.lat, params.radiusKm * 1000)
      idx += 3
    }

    sql += ` ORDER BY boundary_name, monument_number LIMIT $${idx++}`
    values.push(params.limit)

    const { rows } = await db.query<BoundaryMonumentRow>(sql, values)

    return NextResponse.json({ data: rows, count: rows.length })
  },
)

/**
 * POST /api/boundary-monuments
 *
 * Create a new boundary monument.
 */
const createSchema = z.object({
  monument_number: z.string().min(1).max(100),
  monument_type: z.string().prefault('pillar'),
  boundary_name: z.string().min(1).max(200),
  treaty_reference: z.string().min(1).max(500),
  treaty_date: z.string().optional(),
  latitude: z.number().finite().min(-90).max(90).optional(),
  longitude: z.number().finite().min(-180).max(180).optional(),
  elevation: z.number().finite().optional(),
  easting: z.number().finite().optional(),
  northing: z.number().finite().optional(),
  coordinate_epoch: z.number().optional(),
  reference_frame: z.string().prefault('ITRF2014'),
  observation_date: z.string().optional(),
  sigma_e: z.number().optional(),
  sigma_n: z.number().optional(),
  sigma_h: z.number().optional(),
  sigma_en: z.number().prefault(0),
  confidence_level: z.number().prefault(0.95),
  physical_description: z.string().optional(),
  material: z.string().optional(),
  dimensions: z.string().optional(),
  marker_text: z.string().optional(),
  photo_url: z.string().optional(),
  county: z.string().optional(),
  sub_county: z.string().optional(),
  locality: z.string().optional(),
  sheet_number: z.string().optional(),
  condition: z.string().prefault('good'),
  condition_notes: z.string().optional(),
  last_inspected_date: z.string().optional(),
  verification_status: z.string().prefault('pending'),
  verified_by: z.string().optional(),
  verified_date: z.string().optional(),
  verification_notes: z.string().optional(),
  metadata: z.record(z.string(), z.unknown()).prefault({}),
}).and(declaredUtmReferenceSchema).transform((body, ctx) => {
  // Validate ranges only after the reference intersection succeeds.
  if ((body.easting === undefined) !== (body.northing === undefined)) {
    ctx.addIssue({ code: z.ZodIssueCode.custom, path: ['easting'], message: 'Supply both easting and northing, or leave both unknown.' })
  } else if (body.easting !== undefined && body.northing !== undefined) {
    const range = validateCoordinateRange(body.easting, body.northing, body.epsg_code)
    if (!range.valid) ctx.addIssue({ code: z.ZodIssueCode.custom, path: ['easting'], message: range.errors.join('; ') })
  }
  if ((body.latitude === undefined) !== (body.longitude === undefined)) {
    ctx.addIssue({ code: z.ZodIssueCode.custom, path: ['latitude'], message: 'Supply both latitude and longitude, or leave both unknown.' })
  }
  return body
})

export const POST = apiHandler(
  {
    auth: true,
    schema: createSchema,
    rateLimit: { max: 30, windowMs: 60000 },
    auditChain: {
      entityType: 'document',
      action: 'create',
      reason: 'Boundary monument created',
    },
  },
  async (_req, ctx) => {
    const body = ctx.body as z.infer<typeof createSchema>

    // Build the geometry if lat/lon provided
    const values: unknown[] = []
    const cols: string[] = []
    const placeholders: string[] = []
    let idx = 1

    for (const [key, val] of Object.entries(body)) {
      if (val === undefined) continue
      cols.push(key)
      values.push(val)
      placeholders.push(`$${idx++}`)
    }

    // Add created_by
    cols.push('created_by')
    values.push(ctx.userId)
    placeholders.push(`$${idx++}`)

    // Add geom if lat + lon provided
    if (body.latitude !== undefined && body.longitude !== undefined) {
      cols.push('geom')
      values.push(`SRID=4326;POINT(${body.longitude} ${body.latitude})`)
      placeholders.push(`ST_GeomFromText($${idx++}, 4326)`)
    }

    const sql = `INSERT INTO boundary_monuments (${cols.join(', ')}) VALUES (${placeholders.join(', ')}) RETURNING *`
    const { rows } = await db.query<BoundaryMonumentRow>(sql, values)

    return NextResponse.json({ data: rows[0] }, { status: 201 })
  },
)
